export function evaluate({ inputs, time, seed, state }) {
  const { launchSpeed, gravity, mass } = inputs;
  // time is seconds since launch
  const t = time;
  // physics
  const velocity = launchSpeed - gravity * t;
  const acceleration = -gravity;
  const force = mass * gravity;
  const height = launchSpeed * t - gravity * t * t / 2;
  const apexTime = launchSpeed / gravity;
  const apexHeight = launchSpeed * launchSpeed / (2 * gravity);
  // motion state
  let motionState = "Rising";
  if (t < apexTime - 0.0001) motionState = "Rising";
  else if (t > apexTime + 0.0001) motionState = "Falling";
  else motionState = "At the top";
  // layout constants (pixels)
  const laneX = 20, laneY = 20, laneW = 300, laneH = 380;
  const plotX = 340, plotY = 20, plotW = 300, plotH = 380;
  // ball position on height ruler (0-2.2 m maps to laneH)
  const maxHeight = 2.2;
  const ballY = laneY + laneH - (height / maxHeight) * laneH;
  const ballX = laneX + laneW / 2;
  // velocity arrow
  const velScale = 20; // pixels per (m/s)
  const velLen = velocity * velScale;
  const velDir = velLen >= 0 ? "up" : "down";
  const velAbs = Math.abs(velLen);
  // acceleration arrow (dashed warm)
  const accScale = 20;
  const accLen = acceleration * accScale;
  const accDir = accLen >= 0 ? "up" : "down";
  const accAbs = Math.abs(accLen);
  // callout lines
  const calloutLines = [
    `v = ${sdk.format(velocity, 2)} m/s`,
    `a = ${sdk.format(acceleration, 2)} m/s²`,
    `F = ${sdk.format(force, 2)} N`
  ];
  // plot data (velocity vs time)
  const tEnd = inputs.launchSpeed * 2 / inputs.gravity; // enough to show full curve
  const points = [];
  const sampleCount = 24;
  for (let i = 0; i <= sampleCount; i++) {
    const ti = (i / sampleCount) * tEnd;
    const vi = launchSpeed - gravity * ti;
    points.push({ x: ti, y: vi });
  }
  // current point on plot
  const plotCurrent = { x: t, y: velocity };
  // slope segment (local a = -g)
  const slopeX0 = t - 0.05;
  const slopeX1 = t + 0.05;
  const slopeY0 = launchSpeed - gravity * slopeX0;
  const slopeY1 = launchSpeed - gravity * slopeX1;
  // build objects
  const objects = [];
  // left lane panel
  objects.push(...sdk.panel({ x: laneX, y: laneY, w: laneW, h: laneH, title: "Motion", state: motionState, id: "lane.motion" }));
  // height ruler (simple line)
  objects.push(sdk.line("ruler", laneX + laneW / 2 - 30, laneY + laneH, laneX + laneW / 2 - 30, laneY));
  // ball
  objects.push(sdk.circle("ball.toss", ballX, ballY, 24, { role: "neutral" }));
  // velocity arrow
  objects.push(sdk.vector("vec.v", { x: ballX, y: ballY }, { value: velAbs, direction: velDir }, { scale: 1, label: "v", role: "output" }));
  // acceleration arrow (dashed warm – using vector with style via options not needed, just label)
  objects.push(sdk.vector("vec.a", { x: ballX, y: ballY }, { value: accAbs, direction: accDir }, { scale: 1, label: "a", role: "output" }));
  // callout beside ball
  objects.push(...sdk.callout(ballX + 30, ballY - 30, calloutLines, { id: "callout.toss" }));
  // right plot panel
  objects.push(...sdk.panel({ x: plotX, y: plotY, w: plotW, h: plotH, title: "v‑t", state: "", id: "lane.plot" }));
  // plot axes and curve
  objects.push(sdk.plot("plot.vt", {
    x: plotX,
    y: plotY,
    w: plotW,
    h: plotH,
    axes: {
      x: { label: "t (s)", min: 0, max: tEnd, unit: "s" },
      y: { label: "v (m/s)", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      { label: "v(t)", kind: "line", points: points },
      { label: "current", kind: "scatter", points: [plotCurrent] },
      { label: "slope", kind: "line", points: [{ x: slopeX0, y: slopeY0 }, { x: slopeX1, y: slopeY1 }], role: "output" }
    ]
  }));
  // frame
  const frame = sdk.frame(objects, { width: 660, height: 420 });
  // quantities to report (optional, not required by card)
  const quantities = {
    launchSpeed,
    gravity,
    mass,
    apexTime,
    apexHeight,
    height,
    velocity,
    acceleration,
    force
  };
  return { frame, quantities };
}
